CREATE TABLE hg_push_devices(id uuid PRIMARY KEY,household_id uuid NOT NULL,user_id integer NOT NULL,installation_id uuid NOT NULL,token_encrypted text NOT NULL,platform text NOT NULL DEFAULT 'android',enabled boolean NOT NULL DEFAULT true,last_seen timestamptz NOT NULL DEFAULT now(),UNIQUE(household_id,user_id,installation_id),FOREIGN KEY(household_id,user_id) REFERENCES hg_memberships(household_id,user_id));
CREATE TABLE hg_notification_preferences(household_id uuid NOT NULL,user_id integer NOT NULL,categories text[] NOT NULL DEFAULT ARRAY['SECURITY','MOVEMENT','EMERGENCY','SYSTEM'],quiet_start text,quiet_end text,critical_demo_override boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(household_id,user_id),FOREIGN KEY(household_id,user_id) REFERENCES hg_memberships(household_id,user_id));
CREATE TABLE hg_notifications(id uuid PRIMARY KEY,household_id uuid NOT NULL,event_id uuid NOT NULL REFERENCES hg_events(id),user_id integer NOT NULL,installation_id uuid NOT NULL,status text NOT NULL CHECK(status IN ('QUEUED','SENDING','SENT','FAILED','UNKNOWN','SKIPPED')),provider_ticket text,provider_receipt jsonb,error_code text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,installation_id));
CREATE TABLE hg_emergency_profiles(household_id uuid PRIMARY KEY REFERENCES hg_households(id),data jsonb NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1,updated_by integer,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hg_emergency_policies(household_id uuid PRIMARY KEY REFERENCES hg_households(id),enabled boolean NOT NULL DEFAULT false,immobility_seconds integer NOT NULL DEFAULT 10 CHECK(immobility_seconds BETWEEN 5 AND 120),response_seconds integer NOT NULL DEFAULT 20 CHECK(response_seconds BETWEEN 10 AND 300),transport text NOT NULL DEFAULT 'SIMULATED' CHECK(transport='SIMULATED'),revision integer NOT NULL DEFAULT 1);
CREATE TABLE hg_emergency_incidents(id uuid PRIMARY KEY,household_id uuid NOT NULL,event_id uuid UNIQUE NOT NULL REFERENCES hg_events(id),state text NOT NULL CHECK(state IN ('PENDING_RESPONSE','CANCELLED','ESCALATED','CALLING_SIMULATED','CONNECTED_SIMULATED','CLOSED','FAILED','NEEDS_REVIEW')),response_deadline timestamptz NOT NULL,policy_snapshot jsonb NOT NULL,profile_snapshot jsonb NOT NULL,operator_id integer,state_revision integer NOT NULL DEFAULT 1,cancellation_requested boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(household_id,id));
CREATE TABLE hg_simulated_calls(id uuid PRIMARY KEY,household_id uuid NOT NULL,incident_id uuid UNIQUE NOT NULL REFERENCES hg_emergency_incidents(id),state text NOT NULL CHECK(state IN ('RINGING','CONNECTED','CLOSED','CANCELLED','FAILED')),audio_ref text,audio_status text NOT NULL DEFAULT 'PENDING' CHECK(audio_status IN ('PENDING','READY','UNAVAILABLE','FAILED')),transcript text NOT NULL,attempts integer NOT NULL DEFAULT 0,accepted_at timestamptz,closed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hg_actuator_commands(id uuid PRIMARY KEY,household_id uuid NOT NULL,legacy_code text NOT NULL,requested_state text NOT NULL CHECK(requested_state IN ('ON','OFF')),confirmed_state text CHECK(confirmed_state IN ('ON','OFF')),confirmation_source text,source text NOT NULL,event_id uuid,ack_at timestamptz,status text NOT NULL DEFAULT 'REQUESTED' CHECK(status IN ('REQUESTED','CONFIRMED','FAILED','CANCELLED')),idempotency_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hg_sensor_signals(id bigserial PRIMARY KEY,household_id uuid NOT NULL,device_id text NOT NULL,sensor_type text NOT NULL,state text NOT NULL,source text NOT NULL CHECK(source IN ('LIVE','SIMULATED')),occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX hg_signal_window ON hg_sensor_signals(household_id,device_id,sensor_type,occurred_at DESC);
